protocol Importer {
    func parse(_ source: String) -> [Row]        // required step
    func store(_ rows: [Row]) -> Report          // required step
}
extension Importer {
    func run(_ source: String) -> Report {       // the skeleton
        let rows = parse(source)
        beforeStore(rows)                        // call the hook
        return store(rows)
    }
    func beforeStore(_ rows: [Row]) {}           // default hook (declare in protocol to allow overriding)
}
